1	<script setup lang="ts">
2	/**
3	 * Inline new-message compose card: an in-flow card in the central pane (the
4	 * area where the inbox list normally is) — or docked at the bottom of the
5	 * reader pane while a reader is open — never a modal overlay. There is no
6	 * backdrop and no dimming: the rail, header and contact pane stay visible and
7	 * interactive. The editor body (fields, status, errors, conflict/recovery,
8	 * discard-confirm, footer) is the shared DraftEditorCore; this surface only
9	 * supplies the card shell and its header: "New Message", or the reply draft's
10	 * own title when a reply draft is edited here because its source conversation
11	 * cannot host it (then one Amber Notice line says so, with the terse reason as
12	 * visible text and the full sentence in the title).
13	 * No Send action exists.
14	 */
15	import { computed } from 'vue';
16	import type { DraftContent, DraftRef, DraftSource, MailError } from '../lib/ipc/client';
17	import { replyReasonLabel } from '../lib/reply-context';
18	import DraftEditorCore from './DraftEditorCore.vue';
19	
20	const props = defineProps<{
21	  /** Reply drafts only: the human-readable target shown as "Reply draft to {label}"; null hides it. */
22	  recipientLabel?: string | null;
23	  /** Reply drafts only: why the draft is edited here and not in its thread. */
24	  notice?: string | null;
25	  activeRef: DraftRef | null;
26	  source: DraftSource | null;
27	  content: DraftContent;
28	  status: string;
29	  creating: boolean;
30	  saving: boolean;
31	  conflict: boolean;
32	  error: MailError | null;
33	  createError: MailError | null;
34	  deleting: boolean;
35	  closing: boolean;
36	  transitioning: boolean;
37	  deletePending: boolean;
38	  confirmDiscard: boolean;
39	  discardBusy: boolean;
40	  confirmReload: boolean;
41	  copyPending: boolean;
42	  recoveryRequired: boolean;
43	  canCancelReplyPreparation: boolean;
44	  closeError: string | null;
45	}>();
46	
47	/** The card's accessible name: "New Message", or the reply draft's own title. */
48	const title = computed(() => props.source?.kind !== 'reply' ? 'New Message'
49	  : props.recipientLabel ? `Reply draft to ${props.recipientLabel}` : 'Reply draft');
50	
51	/** One Amber line: the terse reason is visible text; the full sentence stays in the title. */
52	const noticeLine = computed(() => props.notice
53	  ? `Source conversation unavailable: ${replyReasonLabel(props.notice)}. Editing locally; nothing is sent.`
54	  : '');
55	
56	const emit = defineEmits<{
57	  closeEditor: [];
58	  setField: [field: keyof DraftContent, value: string];
59	  retry: [];
60	  askDiscard: [];
61	  confirmDiscard: [];
62	  cancelDiscard: [];
63	  askReload: [];
64	  confirmReload: [];
65	  cancelReload: [];
66	  saveAsNew: [];
67	  cancelReplyPreparation: [];
68	}>();
69	
70	function onSetField(field: keyof DraftContent, value: string): void {
71	  emit('setField', field, value);
72	}
73	</script>
74	
75	<template>
76	  <section class="compose-card" :aria-label="title" data-test="compose-card">
77	    <DraftEditorCore
78	      data-test="composer"
79	      autofocus="to"
80	      variant="new"
81	      :active-ref="activeRef"
82	      :source="source"
83	      :content="content"
84	      :status="status"
85	      :creating="creating"
86	      :saving="saving"
87	      :conflict="conflict"
88	      :error="error"
89	      :create-error="createError"
90	      :deleting="deleting"
91	      :closing="closing"
92	      :transitioning="transitioning"
93	      :delete-pending="deletePending"
94	      :confirm-discard="confirmDiscard"
95	      :discard-busy="discardBusy"
96	      :confirm-reload="confirmReload"
97	      :copy-pending="copyPending"
98	      :recovery-required="recoveryRequired"
99	      :can-cancel-reply-preparation="canCancelReplyPreparation"
100	      :close-error="closeError"
101	      @close-editor="emit('closeEditor')"
102	      @set-field="onSetField"
103	      @retry="emit('retry')"
104	      @ask-discard="emit('askDiscard')"
105	      @confirm-discard="emit('confirmDiscard')"
106	      @cancel-discard="emit('cancelDiscard')"
107	      @ask-reload="emit('askReload')"
108	      @confirm-reload="emit('confirmReload')"
109	      @cancel-reload="emit('cancelReload')"
110	      @save-as-new="emit('saveAsNew')"
111	      @cancel-reply-preparation="emit('cancelReplyPreparation')"
112	    >
113	      <template #header>
114	        <header class="composer-heading">
115	          <h2 v-if="source?.kind === 'reply' && recipientLabel">Reply draft <span class="reply-to">to <span data-test="draft-recipient-label">{{ recipientLabel }}</span></span></h2>
116	          <h2 v-else-if="source?.kind === 'reply'">Reply draft</h2>
117	          <h2 v-else>New Message</h2>
118	        </header>
119	        <!-- Honest state: the reply cannot be shown in its thread, so it is edited here. -->
120	        <p v-if="notice" class="compose-card-notice" role="note" data-test="compose-card-notice" :title="notice">{{ noticeLine }}</p>
121	      </template>
122	      <template #context>
123	        <!-- The fixed reply source: attributes only, never visible text. -->
124	        <span
125	          v-if="source?.kind === 'reply'"
126	          hidden
127	          data-test="reply-source"
128	          :data-source-conversation="source.conversation.conversationId"
129	          :data-source-message="source.sourceMessageId"
130	        ></span>
131	      </template>
132	    </DraftEditorCore>
133	  </section>
134	</template>
