1	<script setup lang="ts">
2	/**
3	 * The Drafts list context: one Ash coverage line with a quiet `New draft`
4	 * action, the in-flow recovery and error lines, and one row per local draft.
5	 * Rows are not threads, so they use `ContextRowList` (the 36px list-row
6	 * anatomy and its keyboard model: J/K, arrows, Home, End, roving tabindex).
7	 *
8	 * Opening a draft is the app's decision (`open`): a reply draft goes to its
9	 * source conversation, a new message to the inline compose card. This
10	 * component only lists drafts and reports which one was chosen. The editor
11	 * itself is never mounted here (`DraftEditorCore` lives in the card and the
12	 * docked reply composer), so the list shows only while no editor covers it.
13	 *
14	 * Rows are recipient (Title; Ash `(no recipient)`), subject (Ash
15	 * `(no subject)`) followed by a quiet one-line body preview (Ash; `No text
16	 * yet` for an empty body; nothing while the body is unknown), a quiet
17	 * `Discard` row action, a quiet `Reply` word for reply drafts and the compact
18	 * updated time. The revision is a row title, and a word (`Conflict · revision
19	 * N`, Amber Notice) only while that draft is the one in conflict.
20	 *
21	 * The summary carries no body, so the preview reads each body once through
22	 * `loadBody` (see `useDraftPreviews`). It is plain literal text in a text node.
23	 *
24	 * `Discard` asks first, in a confirmation line under its row with the editor's
25	 * wording. Only `discardDraft` (the app's delete) removes a draft; a failure
26	 * keeps the draft and says so, a success moves focus to the next row (else the
27	 * previous one, else the pane) and announces `Local draft deleted`. A draft
28	 * that is open in the editor cannot be discarded here.
29	 *
30	 * The app's key handler reaches the focused row through `discardRow` (Delete
31	 * or Backspace). It only opens the same confirmation as the button and never
32	 * discards; a row that cannot be discarded (editor open, busy, no `discardDraft`)
33	 * answers `false` and nothing happens.
34	 */
35	import { computed, nextTick, ref } from 'vue';
36	import type { DraftRef, DraftSummary, MailError } from '../lib/ipc/client';
37	import { compactDateLabel, fullDateLabel, machineDateTime } from '../lib/browsing-dates';
38	import { describeDiscardError, isDefiniteDiscardFailure } from '../lib/draft-errors';
39	import { useDraftPreviews } from '../composables/useDraftPreviews';
40	import ContextRowList from './ContextRowList.vue';
41	import DraftAlerts from './DraftAlerts.vue';
42	
43	const LOCAL_LINE = 'Local to this device · never sent';
44	const LOCAL_DETAIL = 'Drafts are local to this device and account. No drafts are sent to a mail provider.';
45	
46	interface DraftItem { key: string; draft: DraftSummary }
47	
48	const props = defineProps<{
49	  summaries: readonly DraftSummary[];
50	  /** The remembered current row (restored after a reader or editor round trip). */
51	  activeKey: string | null;
52	  /** The editor's draft, to mark the one in conflict. */
53	  activeRef: DraftRef | null;
54	  conflict: boolean;
55	  suspendedEditor: boolean;
56	  /** Opening or creating is disabled while the editor is closing or switching. */
57	  busy: boolean;
58	  createError: MailError | null;
59	  listError: MailError | null;
60	  subscriptionError: MailError | null;
61	  closeError: string | null;
62	  closeRetryAvailable: boolean;
63	  closeSetupError: string | null;
64	  /** Reads one draft's body for its preview; without it rows show no preview. */
65	  loadBody?: (ref: DraftRef) => Promise<string>;
66	  /** Deletes one draft after the list's confirmation; resolves to null once confirmed, else the error. Without it rows offer no Discard. */
67	  discardDraft?: (draft: DraftSummary, requestId: string) => Promise<MailError | null>;
68	}>();
69	
70	const emit = defineEmits<{
71	  newDraft: [];
72	  open: [draft: DraftSummary];
73	  'update:activeKey': [key: string];
74	  retryDraftSubscription: [];
75	  retryClose: [];
76	  retryCloseSetup: [];
77	}>();
78	
79	/** Stable row key for one draft; the app uses it to remember the current row. */
80	function draftKey(ref: DraftRef): string {
81	  return `${ref.accountId}:${ref.draftId}`;
82	}
83	
84	const items = computed<DraftItem[]>(() => props.summaries.map(draft => ({ key: draftKey(draft.ref), draft })));
85	
86	/** The revision is shown as a word only while this very draft is in conflict. */
87	function inConflict(ref: DraftRef): boolean {
88	  return props.conflict && !!props.activeRef && props.activeRef.accountId === ref.accountId && props.activeRef.draftId === ref.draftId;
89	}
90	
91	function rowTitle(item: DraftItem): string {
92	  return `Revision ${item.draft.revision} · ${item.draft.source.kind === 'reply' ? 'Reply' : 'New message'}`;
93	}
94	
95	function rowLabel(draft: DraftSummary): string {
96	  return draft.to || draft.subject || 'with no recipient or subject';
97	}
98	
99	const { previewFor } = useDraftPreviews(
100	  () => props.summaries,
101	  (ref) => props.loadBody ? props.loadBody(ref) : Promise.reject(new Error('no body loader')),
102	);
103	
104	const list = ref<{ focusRow: (key: string | null, options?: { preventScroll?: boolean }) => Promise<void> } | null>(null);
105	const paneEl = ref<HTMLElement | null>(null);
106	
107	// Discard from the list: one confirmation at a time, under its row.
108	const confirmKey = ref<string | null>(null);
109	const discarding = ref(false);
110	const discardError = ref<MailError | null>(null);
111	const discardStatus = ref('');
112	/** One request id per confirmation, kept across retries so a lost acknowledgement is repeated, not doubled. */
113	let requestId: string | null = null;
114	
115	function newRequestId(): string {
116	  return typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
117	    ? crypto.randomUUID()
118	    : `ui-${Date.now()}-${Math.random().toString(36).slice(2)}`;
119	}
120	
121	/** The editor owns this draft while it is open there, so the list must not delete it. */
122	function editorOwns(ref: DraftRef): boolean {
123	  return !!props.activeRef && props.activeRef.accountId === ref.accountId && props.activeRef.draftId === ref.draftId;
124	}
125	function discardDisabled(item: DraftItem): boolean {
126	  return props.busy || discarding.value || editorOwns(item.draft.ref);
127	}
128	
129	function rowEl(item: DraftItem, selector: string): HTMLElement | null {
130	  return paneEl.value?.querySelector<HTMLElement>(`[data-test="draft-row-${item.draft.ref.draftId}"] ${selector}`) ?? null;
131	}
132	
133	async function askDiscard(item: DraftItem): Promise<void> {
134	  if (!props.discardDraft || discardDisabled(item)) return;
135	  confirmKey.value = item.key;
136	  requestId = newRequestId();
137	  discardError.value = null;
138	  discardStatus.value = '';
139	  await nextTick();
140	  rowEl(item, '[data-test="confirm-discard-draft"]')?.focus();
141	}
142	
143	/** Open the confirmation for the row with this key, like its button. False when the row offers no Discard. */
144	function discardRow(key: string): boolean {
145	  const item = items.value.find(candidate => candidate.key === key);
146	  if (!item || !props.discardDraft || discardDisabled(item)) return false;
147	  void askDiscard(item);
148	  return true;
149	}
150	
151	async function cancelDiscard(item: DraftItem): Promise<void> {
152	  if (discarding.value) return;
153	  confirmKey.value = null;
154	  requestId = null;
155	  await nextTick();
156	  rowEl(item, '[data-test="discard-draft"]')?.focus();
157	}
158	
159	function onConfirmKeydown(event: KeyboardEvent, item: DraftItem): void {
160	  if (event.key !== 'Escape' || event.isComposing || event.keyCode === 229 || event.ctrlKey || event.metaKey || event.altKey) return;
161	  // The confirmation owns this Escape: it must not also run the app's Back.
162	  event.stopPropagation(); event.preventDefault();
163	  void cancelDiscard(item);
164	}
165	
166	async function confirmDiscard(item: DraftItem): Promise<void> {
167	  const send = props.discardDraft;
168	  if (!send || confirmKey.value !== item.key || discarding.value || editorOwns(item.draft.ref)) return;
169	  const index = items.value.findIndex((candidate) => candidate.key === item.key);
170	  const neighbour = items.value[index + 1]?.key ?? items.value[index - 1]?.key ?? null;
171	  discarding.value = true;
172	  discardError.value = null;
173	  discardStatus.value = 'Discarding draft…';
174	  const error = await send(item.draft, requestId ?? newRequestId());
175	  discarding.value = false;
176	  if (!error) {
177	    confirmKey.value = null;
178	    requestId = null;
179	    discardStatus.value = 'Local draft deleted';
180	    await nextTick();
181	    if (neighbour !== null && items.value.some((candidate) => candidate.key === neighbour)) emit('update:activeKey', neighbour);
182	    // `focusRow` falls back to the first row, then to the pane when no row is left.
183	    if (list.value) await list.value.focusRow(neighbour, {});
184	    else paneEl.value?.focus();
185	    return;
186	  }
187	  // The draft stays in the list, and the failure stays visible until the next attempt.
188	  discardStatus.value = '';
189	  discardError.value = error;
190	  if (isDefiniteDiscardFailure(error)) {
191	    confirmKey.value = null;
192	    requestId = null;
193	    await nextTick();
194	    rowEl(item, '[data-test="discard-draft"]')?.focus();
195	  }
196	}
197	
198	/** Focus the current row, or the pane itself when there is no row to take it. */
199	async function focusRow(options: { preventScroll?: boolean } = {}): Promise<void> {
200	  if (list.value) await list.value.focusRow(props.activeKey, options);
201	  else paneEl.value?.focus(options);
202	}
203	defineExpose({ focusRow, discardRow, el: paneEl });
204	</script>
205	
206	<template>
207	  <div ref="paneEl" class="context-pane drafts-pane" data-test="drafts-pane" tabindex="-1">
208	    <!-- Recovery and error lines are in flow above the rows, never hidden. -->
209	    <DraftAlerts
210	      :suspended-editor="suspendedEditor"
211	      :close-error="closeError"
212	      :close-setup-error="closeSetupError"
213	      :close-retry-available="closeRetryAvailable"
214	      :list-error="listError"
215	      :subscription-error="subscriptionError"
216	      :create-error="createError"
217	      @retry-draft-subscription="emit('retryDraftSubscription')"
218	      @retry-close="emit('retryClose')"
219	      @retry-close-setup="emit('retryCloseSetup')"
220	    />
221	
222	    <!-- The one standing local-only line; the sentence is its title and hidden text. -->
223	    <div class="context-coverage">
224	      <p class="cached-coverage" role="note" data-test="drafts-coverage" :title="LOCAL_DETAIL">{{ LOCAL_LINE }}<span class="visually-hidden">. {{ LOCAL_DETAIL }}</span></p>
225	      <button type="button" class="drawer-quiet" data-test="new-draft" :disabled="busy" @click="emit('newDraft')">New draft</button>
226	    </div>
227	
228	    <!-- Discard outcome: the live region stays mounted (zero height when empty) so each result is announced. -->
229	    <p class="draft-discard-status" role="status" aria-live="polite" data-test="draft-discard-status">{{ discardStatus }}</p>
230	    <div v-if="discardError" class="draft-notices">
231	      <p role="alert" class="drawer-alert" data-test="draft-discard-error">{{ describeDiscardError(discardError) }}</p>
232	    </div>
233	
234	    <p v-if="!items.length" class="list-state" data-test="draft-list-empty">No local drafts.</p>
235	    <ContextRowList
236	      v-else
237	      ref="list"
238	      data-test="draft-list"
239	      :items="items"
240	      label="Local drafts"
241	      :active-key="activeKey"
242	      :disabled="busy"
243	      :row-title="rowTitle"
244	      :row-test-id="(item: DraftItem) => `draft-row-${item.draft.ref.draftId}`"
245	      :open-test-id="(item: DraftItem) => `open-draft-${item.draft.ref.draftId}`"
246	      @update:active-key="emit('update:activeKey', $event)"
247	      @open="emit('open', $event.draft)"
248	    >
249	      <template #primary="{ item }"><span class="context-subject" :class="{ 'drawer-empty': !item.draft.to }">{{ item.draft.to || '(no recipient)' }}</span></template>
250	      <template #secondary="{ item }">
251	        <span class="draft-subject" :class="{ 'drawer-empty': !item.draft.subject }">{{ item.draft.subject || '(no subject)' }}</span>
252	        <!-- Plain text node only: a body that looks like HTML stays literal. Nothing while the body is unknown. -->
253	        <span v-if="previewFor(item.draft) !== null" class="draft-preview" :class="{ 'drawer-empty': !previewFor(item.draft) }" data-test="draft-preview">{{ previewFor(item.draft) || 'No text yet' }}</span>
254	      </template>
255	      <template #actions="{ item }">
256	        <button
257	          v-if="discardDraft"
258	          type="button"
259	          class="drawer-quiet"
260	          data-test="discard-draft"
261	          :aria-label="`Discard draft ${rowLabel(item.draft)}`"
262	          :title="editorOwns(item.draft.ref) ? 'This draft is open in an editor' : 'Discard this local draft — Delete'"
263	          aria-keyshortcuts="Delete Backspace"
264	          :aria-expanded="confirmKey === item.key"
265	          :disabled="discardDisabled(item)"
266	          @click="askDiscard(item)"
267	        >Discard</button>
268	      </template>
269	      <template #trailing="{ item }">
270	        <span v-if="inConflict(item.draft.ref)" class="activity-status tone-warn" data-test="draft-row-conflict">Conflict · revision {{ item.draft.revision }}</span>
271	        <span v-if="item.draft.source.kind === 'reply'" class="draft-reply">Reply</span>
272	        <time class="draft-date row-time" :datetime="machineDateTime(item.draft.updatedAt)" :title="fullDateLabel(item.draft.updatedAt)">{{ compactDateLabel(item.draft.updatedAt) }}</time>
273	      </template>
274	      <template #note="{ item }">
275	        <div
276	          v-if="confirmKey === item.key"
277	          class="context-row-note draft-discard-confirm"
278	          role="alertdialog"
279	          aria-label="Confirm discard"
280	          :aria-describedby="`discard-prompt-${item.draft.ref.draftId}`"
281	          data-test="draft-discard-confirm"
282	          @keydown="onConfirmKeydown($event, item)"
283	        >
284	          <span :id="`discard-prompt-${item.draft.ref.draftId}`">Discard this local draft? This cannot be undone.</span>
285	          <button type="button" class="drawer-quiet" data-test="confirm-discard-draft" :disabled="discarding || editorOwns(item.draft.ref)" @click="confirmDiscard(item)">Confirm discard</button>
286	          <button type="button" class="drawer-quiet" data-test="cancel-discard-draft" :disabled="discarding" @click="cancelDiscard(item)">Keep draft</button>
287	        </div>
288	      </template>
289	    </ContextRowList>
290	  </div>
291	</template>
292

1	import type { Conversation } from './ipc/client';
2	
3	/**
4	 * Why a reply cannot be prepared from, or a reply draft cannot be docked in, a
5	 * conversation. `text` is the full sentence (Prepare reply tooltip, the compose
6	 * card's title); `label` is the terse phrase the compose card shows as visible
7	 * text. One table, so the sentence and the phrase cannot drift apart.
8	 */
9	export const REPLY_REASONS = {
10	  noLatestMessage: { text: 'No displayed latest message is available as a reply source.', label: 'no latest message' },
11	  retainedSnapshot: { text: 'Reply preparation is blocked for a retained snapshot; current message headers cannot be verified.', label: 'retained snapshot' },
12	  incomplete: { text: 'Reply preparation is blocked because this cached conversation is incomplete.', label: 'incomplete cached conversation' },
13	  headerMismatch: { text: 'Reply preparation is blocked because cached reply headers do not match the displayed latest message.', label: 'reply headers do not match the latest message' },
14	  otherAccount: { text: 'The source conversation belongs to another account.', label: 'belongs to another account' },
15	  notOpen: { text: 'The source conversation is not open.', label: 'not open' },
16	  stillLoading: { text: 'The source conversation is still loading.', label: 'still loading' },
17	} as const;
18	
19	const LOAD_ERROR_PREFIX = 'The source conversation could not be loaded';
20	
21	/** The reason when the source conversation failed to load; `detail` is the error word ("not found"). */
22	export function sourceLoadErrorReason(detail?: string | null): string {
23	  return detail ? `${LOAD_ERROR_PREFIX}: ${detail}.` : `${LOAD_ERROR_PREFIX}.`;
24	}
25	
26	/**
27	 * The terse visible phrase for a reason sentence ("retained snapshot"). A
28	 * sentence that is not in the table is shown as written, never replaced by a
29	 * vague word.
30	 */
31	export function replyReasonLabel(reason: string): string {
32	  for (const entry of Object.values(REPLY_REASONS)) if (entry.text === reason) return entry.label;
33	  if (reason.startsWith(LOAD_ERROR_PREFIX)) {
34	    const detail = reason.slice(LOAD_ERROR_PREFIX.length).replace(/^:\s*/, '').replace(/\.$/, '');
35	    return detail ? `could not be loaded: ${detail}` : 'could not be loaded';
36	  }
37	  return reason.replace(/\.$/, '');
38	}
39	
40	/**
41	 * The one rule for whether a reply can be prepared from, or a reply draft can
42	 * be docked in, a loaded conversation. `null` means it can. ReaderView uses it
43	 * for the Prepare reply controls and the R key; App uses it to decide whether
44	 * a reply draft opened from the Drafts list docks in the reader.
45	 */
46	export function replyBlockedReason(conversation: Conversation | null | undefined): string | null {
47	  const latest = conversation?.messages.at(-1);
48	  if (!conversation || !latest) return REPLY_REASONS.noLatestMessage.text;
49	  if (conversation.retainedSnapshotAt) return REPLY_REASONS.retainedSnapshot.text;
50	  if (conversation.contextComplete === false) return REPLY_REASONS.incomplete.text;
51	  if (conversation.replyContext && conversation.replyContext.sourceMessageId !== latest.id) return REPLY_REASONS.headerMismatch.text;
52	  return null;
53	}
54

1	<script setup lang="ts">
2	/**
3	 * The draft recovery and error lines, in flow and on the content inset. Each
4	 * line shows only while its state exists, with unchanged wording and hooks.
5	 * The Drafts list shows all of them above its rows; while an editor covers the
6	 * list, the app shows the list and subscription lines here so they stay
7	 * visible (close protection has its own banner then).
8	 */
9	import type { MailError } from '../lib/ipc/client';
10	import { describeDraftError } from '../lib/draft-errors';
11	
12	defineProps<{
13	  suspendedEditor?: boolean;
14	  closeError?: string | null;
15	  closeSetupError?: string | null;
16	  closeRetryAvailable?: boolean;
