  it.each([
    [REPLY_REASONS.noLatestMessage.text, 'no latest message'],
    [REPLY_REASONS.retainedSnapshot.text, 'retained snapshot'],
    [REPLY_REASONS.incomplete.text, 'incomplete cached conversation'],
